  mutate(erw_je_ew = erw / Einwohner) |&gt;
  filter(!is.na(erw_je_ew)) |&gt;
  arrange(desc(erw_je_ew)) |&gt;
  select(landkreis_name, erw, Einwohner, erw_je_ew, alo_quote) |&gt;
  slice(c(1:3, (n() - 2):n())) |&gt;     # die drei höchsten und die drei niedrigsten
  print(n = 6)

